const RUN = [
  [0, 15, 2], [2, 22, 1.5], [3.5, 21, 0.5],
  [4, 21, 3], [7, 24, 1],
  [8, 17, 0.5], [8.5, 19, 0.5], [9, 21, 0.5], [9.5, 22, 0.5], [10, 24, 0.5], [10.5, 26, 0.5], [11, 27, 0.5], [11.5, 29, 0.5],
  [12, 29, 0.25], [12.25, 31, 0.25], [12.5, 29, 0.25], [12.75, 31, 0.25], [13, 29, 0.25], [13.25, 31, 0.25], [13.5, 29, 0.25], [13.75, 31, 0.25], [14, 29, 0.25], [14.25, 31, 0.25], [14.5, 29, 0.25], [14.75, 31, 0.25], [15, 29, 0.25], [15.25, 31, 0.25], [15.5, 29, 0.25], [15.75, 31, 0.25],
]
// the solo: a random walk over the scale, chord tones on the beats (improvise)
const SOLO = improvise({
  start: 80, length: 30, rate: 2, seed: 815, swing: SW, lo: 12, hi: 32,
  phrase: 8, rest: 0.2, hold: 0.3, scale: () => SCALE, chord: x => (chordAt(x)?.[3] ?? [0]).map(n => mod(n, 12)),
}).map(([b, n, d]) => [b - 80, n, d])
const PHRASES = { A: THEME_A, B: THEME_B, BRIDGE, REST, SOLO, RUN }

// who plays which phrase: [start beat, phrase, transpose, stretch (2 = half speed)]
const LEAD = [[0,"REST",0,1],[16,"A",0,1],[48,"REST",0,1],[80,"REST",0,1],[112,"REST",0,1],[128,"A",2,1],[160,"A",0,2]]
const LEAD2 = [[0,"REST",0,1],[16,"REST",0,1],[48,"B",0,1],[80,"SOLO",0,1],[112,"RUN",0,1],[128,"REST",0,1],[160,"REST",0,1]]
const COUNTER = [[0,"REST",0,1],[16,"REST",0,1],[48,"REST",0,1],[80,"REST",0,1],[112,"REST",0,1],[128,"HARMONY",0,1],[160,"REST",0,1]]
// the note of a voice at x → { n, d, τ, u, at } or null
function voiceAt(plan, x) {
  if (x >= END) return null
  let row = null
  for (const r of plan) if (r[0] <= x) row = r
  if (!row) return null
  const [s, name, tr, k] = row, m = notesAt(PHRASES[name] ?? REST, (x - s) / k)
  return m && { n: m.n + tr, d: m.d * k, τ: m.τ * k, u: m.u, at: s + m.at * k }
}
const leadAt = x => voiceAt(LEAD, x)
const lead2At = x => voiceAt(LEAD2, x)
// the counter-voice: HARMONY = the highest chord tone at least a third below the lead (computed from
// the chords); CANON = the lead itself two beats later, an octave down
const counterAt = x => {
  let row = null
  for (const r of COUNTER) if (r[0] <= x) row = r
  if (!row || x >= END) return null
  if (row[1] === 'CANON') {
    const m = x - 2 >= row[0] ? leadAt(x - 2) : null
    return m && { ...m, n: m.n - 12, at: m.at + 2 }
  }
  if (row[1] !== 'HARMONY') return null
  const m = leadAt(x), c = chordAt(x)
  if (!m || !c) return null
  const pcs = c[3].map(n => mod(n, 12))
  for (let n = m.n - 3; n > m.n - 12; n--) if (pcs.includes(mod(n + 60, 12))) return { ...m, n }
  return null
}

// ---- halobell ----------------------------------------------------------------------------------
const track0 = {
  color: '#ffe9a8',
  graph: x => { const m = leadAt(x); return m ? 1.1 + (m.n + 5) * 0.0559 : null },
  midi: x => { const m = leadAt(x); return m && m.u < 0.92 ? [60 + m.n] : [] },
  formula: ["Hb = 0.3v\\sum_{k=1}^{8} a_k e^{-t/T_k}\\big(\\sin 2\\pi\\,0.9996\\,r_k ft + 0.7\\sin 2\\pi\\,1.0004\\,r_k ft\\big)","r = (\\tfrac12, 1, 2^{4/12}, 2^{7/12}, 2, 2.52, 3.01, 4.1)\\quad\\text{— колокол с большой терцией}"],
  audio({ bpm }) {
    const sec = 60 / bpm, p = poly(haloBellTone, { release: 1.6, life: 8 }), fire = trigger(), echo = delay({ time: sec * 1.5, feedback: 0.34, wet: 0.2 }), verb = reverb({ room: 0.95, damp: 0.22, wet: 0.5 })
    return x => {
      const m = leadAt(x)
      if (fire(m ? m.at : null)) p.hit(hz(m.n, C4), 0.72 + 0.16 * hash(floor(4 * x), 3), m.d * sec + 1.6)
      const y = 1.5 * p()
      return verb(...echo(...pan(y, 0.12)))
    }
  },
}

